'use strict';

// MODULES //

var isNegativeZero = require( '@stdlib/math/base/assert/is-negative-zero' );
var isPositiveZero = require( '@stdlib/math/base/assert/is-positive-zero' );
var isnan = require( '@stdlib/math/base/assert/is-nan' );
var floor = require( '@stdlib/math/base/special/floor' );


// FUNCTIONS //

/**
* Tests whether a value is less than another value, where `-0` is considered less than `+0`.
*
* @private
* @param {number} a - first value
* @param {number} b - second value
* @returns {boolean} boolean indicating whether `a` is less than `b`
*
* @example
* var bool = isLessThan( -0.0, 0.0 );
* // returns true
*
* @example
* var bool = isLessThan( 0.0, -0.0 );
* // returns false
*/
function isLessThan( a, b ) {
	return ( a < b || ( a === b && isNegativeZero( a ) && isPositiveZero( b ) ) ); // eslint-disable-line max-len
}


// MAIN //

/**
* Partitions a strided array using quickselect.
*
* @private
* @param {PositiveInteger} N - number of indexed elements
* @param {NonNegativeInteger} k - partition index
* @param {number} order - sort order
* @param {Object} x - input array object
* @param {Collection} x.data - input array data
* @param {Array<Function>} x.accessors - array element accessors
* @param {integer} strideX - stride length
* @param {NonNegativeInteger} offsetX - starting index
* @returns {Object} input array object
*
* @example
* var toAccessorArray = require( '@stdlib/array/base/to-accessor-array' );
* var arraylike2object = require( '@stdlib/array/base/arraylike2object' );
*
* var x = [ 1.0, -2.0, 3.0, -4.0 ];
*
* gpartitionqs( x.length, 1, 1.0, arraylike2object( toAccessorArray( x ) ), 1, 0 );
*
* console.log( x );
* // => [ -4.0, -2.0, 3.0, 1.0 ]
*/
function gpartitionqs( N, k, order, x, strideX, offsetX ) {
	var xbuf;
	var xget;
	var xset;
	var lo;
	var hi;
	var ix;
	var jx;
	var n;
	var v;
	var t;
	var i;
	var j;

	// Cache reference to array data:
	xbuf = x.data;

	// Cache references to element accessors:
	xget = x.accessors[ 0 ];
	xset = x.accessors[ 1 ];

	// For a positive stride, partitioning in decreasing order is equivalent to providing a negative stride and partitioning in increasing order, and, for a negative stride, partitioning in decreasing order is equivalent to providing a positive stride and partitioning in increasing order...
	if ( order < 0.0 ) {
		strideX *= -1;
		offsetX -= (N-1) * strideX;

		// Reversing the traversal order requires mapping the target index to its mirrored position:
		k = N - k - 1;
	}
	// Move `NaN` values to the end, such that `n` is the number of non-`NaN` values...
	n = N;
	i = 0;
	while ( i < n ) {
		ix = offsetX + (i*strideX);
		if ( isnan( xget( xbuf, ix ) ) ) {
			n -= 1;
			jx = offsetX + (n*strideX);
			t = xget( xbuf, ix );
			xset( xbuf, ix, xget( xbuf, jx ) );
			xset( xbuf, jx, t );
		} else {
			i += 1;
		}
	}
	// If the target index resolves to a `NaN` value, we are finished, as all non-`NaN` values precede `NaN` values...
	if ( k >= n ) {
		return x;
	}
	lo = 0;
	hi = n - 1;
	while ( hi > lo ) {
		// Check whether only two elements remain...
		if ( hi === lo+1 ) {
			ix = offsetX + (lo*strideX);
			jx = offsetX + (hi*strideX);
			if ( isLessThan( xget( xbuf, jx ), xget( xbuf, ix ) ) ) {
				t = xget( xbuf, ix );
				xset( xbuf, ix, xget( xbuf, jx ) );
				xset( xbuf, jx, t );
			}
			return x;
		}
		// Move the middle element to the second position:
		i = lo + 1;
		j = lo + floor( (hi-lo)/2 );
		ix = offsetX + (i*strideX);
		jx = offsetX + (j*strideX);
		t = xget( xbuf, ix );
		xset( xbuf, ix, xget( xbuf, jx ) );
		xset( xbuf, jx, t );

		// Order the first, second, and last elements such that the second element is the median of the three and the first and last elements serve as sentinels during partitioning...
		ix = offsetX + (lo*strideX);
		jx = offsetX + (hi*strideX);
		if ( isLessThan( xget( xbuf, jx ), xget( xbuf, ix ) ) ) {
			t = xget( xbuf, ix );
			xset( xbuf, ix, xget( xbuf, jx ) );
			xset( xbuf, jx, t );
		}
		ix = offsetX + (i*strideX);
		if ( isLessThan( xget( xbuf, jx ), xget( xbuf, ix ) ) ) {
			t = xget( xbuf, ix );
			xset( xbuf, ix, xget( xbuf, jx ) );
			xset( xbuf, jx, t );
		}
		jx = offsetX + (lo*strideX);
		if ( isLessThan( xget( xbuf, ix ), xget( xbuf, jx ) ) ) {
			t = xget( xbuf, ix );
			xset( xbuf, ix, xget( xbuf, jx ) );
			xset( xbuf, jx, t );
		}
		// Use the median of the three as the pivot:
		v = xget( xbuf, ix );

		// Partition the remaining elements such that elements less than or equal to the pivot precede elements greater than or equal to the pivot...
		j = hi;
		while ( true ) {
			// Find an element from the left which is not less than the pivot...
			i += 1;
			ix = offsetX + (i*strideX);
			while ( isLessThan( xget( xbuf, ix ), v ) ) {
				i += 1;
				ix = offsetX + (i*strideX);
			}
			// Find an element from the right which is not greater than the pivot...
			j -= 1;
			jx = offsetX + (j*strideX);
			while ( isLessThan( v, xget( xbuf, jx ) ) ) {
				j -= 1;
				jx = offsetX + (j*strideX);
			}
			// Check whether the scans have crossed...
			if ( j < i ) {
				break;
			}
			t = xget( xbuf, ix );
			xset( xbuf, ix, xget( xbuf, jx ) );
			xset( xbuf, jx, t );
		}
		// Move the pivot into its final position:
		ix = offsetX + ((lo+1)*strideX);
		xset( xbuf, ix, xget( xbuf, jx ) );
		xset( xbuf, jx, v );

		// Continue with the partition containing the target index...
		if ( j === k ) {
			return x;
		}
		if ( j > k ) {
			hi = j - 1;
		} else if ( i > k ) {
			// The target index resides between the two partitions, and, thus, the element at the target index is equal to the pivot:
			return x;
		} else {
			lo = i;
		}
	}
	return x;
}


// EXPORTS //

module.exports = gpartitionqs;
